UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi erbjuder anpassningsbara lösningar för grossist- och uthyrningsföretag i Norden, med fokus på att affärssystemet stödjer er verksamhetsutveckling. Ni får en skräddarsydd lösning som växer med era behov.'::text), true), '{bc,keyPoints}', jsonb_build_array('Anpassar BC för grossist och uthyrning.', 'Fastpris startlösning för snabb implementering.', 'Skräddarsyr systemet för era behov.', 'Lång erfarenhet av Microsofts produkter.'), true) WHERE id = '4097cfef-2af6-4aaf-8fbe-69c388c16d8d'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{sales,whyChoose}', to_jsonb('Vi hjälper er analysera kunddata för att skräddarsy marknadsinsatser. Våra lösningar bidrar till ökad försäljning.'::text), true), '{sales,keyPoints}', jsonb_build_array('Skräddarsydda marknadsinsatser baserade på data.', 'Bättre kundinsikter leder till ökad försäljning.', 'Vi har erfarenhet inom grossist och tillverkning.'), true) WHERE id = '4097cfef-2af6-4aaf-8fbe-69c388c16d8d'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{service,whyChoose}', to_jsonb('Vi hjälper nordiska företag inom konsulttjänster att implementera flexibla och skalbara kundservice-lösningar. Vårt fokus är att ni ska få verktygen för att förbättra er service och effektivitet.'::text), true), '{service,keyPoints}', jsonb_build_array('Vi levererar flexibla kundservicelösningar anpassade för konsulttjänster.', 'Vi erbjuder skalbara lösningar för nordiska företag.', 'Vi möjliggör effektiv ärendehantering och omnikanal-support.', 'Vi har levererat lösningar i över 20 år.'), true) WHERE id = '4097cfef-2af6-4aaf-8fbe-69c388c16d8d'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi hjälper er med ett integrerat affärssystem som enkelt skalar. Detta ger er en effektivare verksamhet med enhetlig data som underlättar beslutsfattande.'::text), true), '{bc,keyPoints}', jsonb_build_array('Tillhandahåller Busienss Central för tillverkning, grossist, distribution och retail.', 'Bistår med implementering och anpassning för er verksamhet.', 'Vi erbjuder system som hanterar redovisning, försäljning och marknadsföring.', 'Ger stöd för flexibla och effektiva administrativa processer.'), true) WHERE id = '674e19f3-b48c-4bf1-86ea-81c2170b178b'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{sales,whyChoose}', to_jsonb('Vi hjälper er att samla försäljnings-, service- och marknadsföringsfunktioner på en enhetlig plattform. Med oss får ni en samlad bild av kundinteraktioner och optimerar processer för ökad effektivitet.'::text), true), '{sales,keyPoints}', jsonb_build_array('Vi skapar en helhetslösning med D365 för er digitala marknadsföring.', 'Vi konsoliderar försäljnings-, service- och marknadsföringsfunktioner.', 'Vi effektiviserar säljprocesser, kunddata och marknadsinsatser.', 'Vi erbjuder implementering och integration av D365 applikationer.'), true) WHERE id = '674e19f3-b48c-4bf1-86ea-81c2170b178b'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{service,whyChoose}', to_jsonb('Vi hjälper er effektivisera kundtjänsten, sänka hanteringstiden och öka kundnöjdheten inom grossist, tillverkning eller retail. Vårt mål är att förvandla supportinteraktioner till positiva upplevelser.'::text), true), '{service,keyPoints}', jsonb_build_array('Omnikanalstrategi med Dynamics 365 Customer Service.', 'Effektiviserar ärendeflöden och sänker hanteringstiden.', 'Anpassar systemet till era specifika processer och behov.', 'Integrerar Customer Service med övriga D365-applikationer.'), true) WHERE id = '674e19f3-b48c-4bf1-86ea-81c2170b178b'; UPDATE partners SET product_filters = jsonb_set(jsonb_set(product_filters, '{bc,whyChoose}', to_jsonb('Vi hjälper medelstora grossister och tillverkare i Norden effektivisera affärsprocesser i Business Central. Vi erbjuder